"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  MicrophoneIcon as PhMic,
  MicrophoneSlashIcon as PhMicSlash,
  VideoCameraIcon as PhCamera,
  VideoCameraSlashIcon as PhCameraSlash,
  KeyboardIcon as PhKeyboard,
  CheckIcon as PhCheck,
  ArrowCounterClockwiseIcon as PhReset,
} from "@phosphor-icons/react";

type Capability = "microphone" | "camera";
type Status = "idle" | "asking" | "granted" | "fallback";
type FallbackReason = "declined" | "denied" | "unsupported";

interface CapabilityConfig {
  title: string;
  subtitle: string;
  askCopy: string;
  allowLabel: string;
  activeLabel: string;
  pausedLabel: string;
  constraints: MediaStreamConstraints;
  fallback: Record<FallbackReason, string>;
}

const AVATAR_SWATCHES = [
  { id: "slate", label: "Slate", className: "bg-slate-400 dark:bg-slate-500" },
  { id: "emerald", label: "Emerald", className: "bg-emerald-500" },
  { id: "amber", label: "Amber", className: "bg-amber-500" },
  { id: "rose", label: "Rose", className: "bg-rose-500" },
] as const;

const CAPABILITY: Record<Capability, CapabilityConfig> = {
  microphone: {
    title: "Voice notes",
    subtitle: "Speak your notes instead of typing.",
    askCopy: "To transcribe your voice notes, this needs your microphone. You can still type instead, any time.",
    allowLabel: "Allow microphone",
    activeLabel: "Listening for your note.",
    pausedLabel: "Microphone paused.",
    constraints: { audio: true },
    fallback: {
      declined: "You can turn voice notes on anytime.",
      denied: "Microphone access was blocked. Allow it from your browser's site settings, or keep typing.",
      unsupported: "Voice notes aren't supported in this browser. Typing still works great.",
    },
  },
  camera: {
    title: "Video avatar",
    subtitle: "Use a live camera preview instead of a color avatar.",
    askCopy: "To set a live video avatar, this needs your camera. You can still pick a color avatar instead, any time.",
    allowLabel: "Allow camera",
    activeLabel: "Camera is on.",
    pausedLabel: "Camera paused.",
    constraints: { video: true },
    fallback: {
      declined: "You can turn the camera on anytime.",
      denied: "Camera access was blocked. Allow it from your browser's site settings, or keep your color avatar.",
      unsupported: "Camera preview isn't supported in this browser. Your color avatar still works great.",
    },
  },
};

function MicIcon() {
  return <PhMic size={15} aria-hidden />;
}
function MicSlashIcon() {
  return <PhMicSlash size={15} aria-hidden />;
}
function CameraIcon() {
  return <PhCamera size={15} aria-hidden />;
}
function CameraSlashIcon() {
  return <PhCameraSlash size={15} aria-hidden />;
}
function KeyboardIcon() {
  return <PhKeyboard size={14} aria-hidden />;
}
function CheckIcon() {
  return <PhCheck size={11} weight="bold" aria-hidden />;
}
function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}

interface PermissionNegotiatorProps {
  capability?: Capability;
  className?: string;
}

export function PermissionNegotiator({ capability = "microphone", className }: PermissionNegotiatorProps) {
  const [status, setStatus] = useState<Status>("idle");
  const [mediaOn, setMediaOn] = useState(false);
  const [requesting, setRequesting] = useState(false);
  const [fallbackReason, setFallbackReason] = useState<FallbackReason>("declined");
  const [note, setNote] = useState("");
  const [avatarColor, setAvatarColor] = useState<(typeof AVATAR_SWATCHES)[number]["id"] | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const config = CAPABILITY[capability];
  const isCamera = capability === "camera";

  useEffect(() => {
    return () => {
      streamRef.current?.getTracks().forEach((t) => t.stop());
    };
  }, []);

  useEffect(() => {
    if (status === "fallback" && !isCamera) textareaRef.current?.focus();
  }, [status, isCamera]);

  useEffect(() => {
    if (isCamera && videoRef.current) {
      videoRef.current.srcObject = status === "granted" && mediaOn ? streamRef.current : null;
    }
  }, [isCamera, status, mediaOn]);

  const requestMedia = async () => {
    if (!navigator.mediaDevices?.getUserMedia) {
      setStatus("fallback");
      setFallbackReason("unsupported");
      return;
    }
    setRequesting(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia(config.constraints);
      streamRef.current = stream;
      setStatus("granted");
      setMediaOn(true);
    } catch (err) {
      const denied = err instanceof DOMException && err.name === "NotAllowedError";
      setStatus("fallback");
      setFallbackReason(denied ? "denied" : "unsupported");
    } finally {
      setRequesting(false);
    }
  };

  const decline = () => {
    setStatus("fallback");
    setFallbackReason("declined");
  };

  const toggleMedia = async () => {
    if (mediaOn) {
      streamRef.current?.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
      setMediaOn(false);
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia(config.constraints);
      streamRef.current = stream;
      setMediaOn(true);
    } catch {
      setStatus("fallback");
      setFallbackReason("denied");
    }
  };

  const iconKey = status === "granted" && !mediaOn ? "off" : "on";
  const OnIcon = isCamera ? CameraIcon : MicIcon;
  const OffIcon = isCamera ? CameraSlashIcon : MicSlashIcon;
  const fade = shouldReduceMotion
    ? { initial: { opacity: 0 }, animate: { opacity: 1 }, exit: { opacity: 0 } }
    : { initial: { height: 0, opacity: 0 }, animate: { height: "auto", opacity: 1 }, exit: { height: 0, opacity: 0 } };

  return (
    <div className={className}>
      <div className="w-full overflow-hidden rounded-2xl border border-slate-200/70 bg-white/95 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center gap-3 p-5">
          <span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
            {status === "granted" && mediaOn && !isCamera && !shouldReduceMotion && (
              <motion.span
                aria-hidden
                className="absolute inset-[-4px] rounded-full border border-emerald-400/60"
                animate={{ scale: [1, 1.35], opacity: [0.6, 0] }}
                transition={{ duration: 1.1, repeat: Infinity, ease: "easeOut" }}
              />
            )}
            <AnimatePresence mode="wait" initial={false}>
              <motion.span
                key={iconKey}
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
                transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
              >
                {iconKey === "off" ? <OffIcon /> : <OnIcon />}
              </motion.span>
            </AnimatePresence>
          </span>
          <div className="min-w-0 flex-1">
            <p className="text-sm font-medium text-slate-900 dark:text-white">{config.title}</p>
            <p className="text-xs text-slate-400 dark:text-slate-500">
              {status === "granted" ? (mediaOn ? config.activeLabel : config.pausedLabel) : config.subtitle}
            </p>
          </div>
          {status === "idle" && (
            <motion.button
              type="button"
              onClick={() => setStatus("asking")}
              whileHover={shouldReduceMotion ? undefined : { y: -1 }}
              whileTap={shouldReduceMotion ? undefined : { scale: 0.95 }}
              className="inline-flex shrink-0 items-center rounded-lg bg-emerald-600 px-3 py-1.5 text-sm font-medium text-white transition-colors hover:bg-emerald-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
            >
              Try it
            </motion.button>
          )}
          {status === "granted" && (
            <motion.button
              type="button"
              onClick={toggleMedia}
              aria-pressed={mediaOn}
              whileHover={shouldReduceMotion ? undefined : { y: -1 }}
              whileTap={shouldReduceMotion ? undefined : { scale: 0.95 }}
              className={`inline-flex shrink-0 items-center rounded-lg px-3 py-1.5 text-sm font-medium transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                mediaOn
                  ? "bg-amber-500/10 text-amber-700 hover:bg-amber-500/15 dark:text-amber-400"
                  : "border border-slate-200/70 text-slate-600 hover:bg-black/5 dark:border-white/10 dark:text-slate-300 dark:hover:bg-white/10"
              }`}
            >
              {mediaOn ? "Stop" : "Resume"}
            </motion.button>
          )}
        </div>

        <AnimatePresence initial={false}>
          {isCamera && status === "granted" && mediaOn && (
            <motion.div
              {...fade}
              transition={shouldReduceMotion ? { duration: 0.15 } : { height: { duration: 0.35, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.25 } }}
              className="overflow-hidden border-t border-slate-200/70 dark:border-white/10"
            >
              <div className="p-4">
                <video
                  ref={videoRef}
                  autoPlay
                  muted
                  playsInline
                  className="aspect-video w-full scale-x-[-1] rounded-lg bg-slate-900 object-cover"
                />
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <AnimatePresence initial={false}>
          {status === "asking" && (
            <motion.div
              {...fade}
              transition={shouldReduceMotion ? { duration: 0.15 } : { height: { duration: 0.35, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.25 } }}
              className="overflow-hidden border-t border-slate-200/70 dark:border-white/10"
            >
              <div className="p-4">
                <p className="text-xs leading-relaxed text-slate-500 dark:text-slate-400">{config.askCopy}</p>
                <div className="mt-3 flex items-center justify-end gap-2">
                  <motion.button
                    type="button"
                    onClick={decline}
                    whileTap={shouldReduceMotion ? undefined : { scale: 0.96 }}
                    className="inline-flex items-center rounded-lg px-3 py-1.5 text-sm font-medium text-slate-600 transition-colors hover:bg-black/5 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:text-slate-300 dark:hover:bg-white/10"
                  >
                    {isCamera ? "Not now, I'll pick a color" : "Not now, I'll type"}
                  </motion.button>
                  <motion.button
                    type="button"
                    disabled={requesting}
                    onClick={requestMedia}
                    whileHover={shouldReduceMotion || requesting ? undefined : { y: -1 }}
                    whileTap={shouldReduceMotion || requesting ? undefined : { scale: 0.96 }}
                    className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-600 px-3.5 py-1.5 text-sm font-medium text-white transition-colors hover:bg-emerald-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 disabled:cursor-wait disabled:opacity-70"
                  >
                    {requesting ? "Waiting for permission…" : config.allowLabel}
                  </motion.button>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <AnimatePresence initial={false}>
          {status === "fallback" && (
            <motion.div
              {...fade}
              transition={shouldReduceMotion ? { duration: 0.15 } : { height: { duration: 0.35, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.25 } }}
              className="overflow-hidden border-t border-slate-200/70 dark:border-white/10"
            >
              <div className="p-4">
                <p className="mb-2 text-xs leading-relaxed text-slate-500 dark:text-slate-400">{config.fallback[fallbackReason]}</p>
                {isCamera ? (
                  <div className="flex items-center gap-2.5">
                    {AVATAR_SWATCHES.map((swatch) => (
                      <motion.button
                        key={swatch.id}
                        type="button"
                        aria-pressed={avatarColor === swatch.id}
                        aria-label={`Use ${swatch.label} avatar`}
                        onClick={() => setAvatarColor(swatch.id)}
                        whileTap={shouldReduceMotion ? undefined : { scale: 0.88 }}
                        className={`relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full ring-2 ring-offset-2 ring-offset-white transition-shadow dark:ring-offset-neutral-950 ${swatch.className} ${
                          avatarColor === swatch.id ? "ring-slate-900 dark:ring-white" : "ring-transparent"
                        }`}
                      >
                        <AnimatePresence>
                          {avatarColor === swatch.id && (
                            <motion.span
                              key="check"
                              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                              animate={{ opacity: 1, scale: 1 }}
                              exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                              transition={{ type: "spring", stiffness: 500, damping: 28 }}
                              className="text-white"
                            >
                              <CheckIcon />
                            </motion.span>
                          )}
                        </AnimatePresence>
                      </motion.button>
                    ))}
                  </div>
                ) : (
                  <div className="flex items-start gap-2 rounded-lg border border-slate-200/70 bg-slate-50/60 px-3 py-2 dark:border-white/10 dark:bg-white/5">
                    <span className="mt-0.5 shrink-0 text-slate-400">
                      <KeyboardIcon />
                    </span>
                    <textarea
                      ref={textareaRef}
                      value={note}
                      onChange={(e) => setNote(e.target.value)}
                      rows={2}
                      placeholder="Type your note here"
                      className="flex-1 resize-none bg-transparent text-sm text-slate-800 placeholder:text-slate-400 focus:outline-none dark:text-slate-100"
                    />
                  </div>
                )}
                <button
                  type="button"
                  onClick={() => setStatus("asking")}
                  className="mt-2 text-xs font-medium text-emerald-600 underline-offset-2 transition-colors hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-emerald-400"
                >
                  {isCamera ? "Enable camera" : "Enable voice"}
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <span className="sr-only" role="status" aria-live="polite">
          {status === "granted" ? (mediaOn ? config.activeLabel : config.pausedLabel) : status === "fallback" ? config.fallback[fallbackReason] : ""}
        </span>
      </div>
    </div>
  );
}
